import { agentNativePath } from "./api-path.js";
import { assertAgentNativeApiEnabled } from "./api-surface.js";
import { getBrowserTabId } from "./browser-tab-id.js";
const APP_STATE_KEY_PATTERN = /^[a-zA-Z0-9_:-]+$/;
function appStateUrl(key) {
    if (!APP_STATE_KEY_PATTERN.test(key)) {
        throw new TypeError("Application state keys may only contain letters, numbers, underscores, hyphens, and colons.");
    }
    return agentNativePath(`/_agent-native/application-state/${key}`);
}
function buildHeaders(requestSource) {
    const headers = {
        "Content-Type": "application/json",
    };
    if (typeof window !== "undefined") {
        headers["X-Agent-Native-Browser-Tab"] = getBrowserTabId();
    }
    if (requestSource)
        headers["X-Request-Source"] = requestSource;
    return headers;
}
function browserTabHeaders() {
    return typeof window === "undefined"
        ? undefined
        : { "X-Agent-Native-Browser-Tab": getBrowserTabId() };
}
async function parseAppStateResponse(response, operation) {
    let raw = "";
    try {
        raw = await response.text();
    }
    catch (err) {
        const cause = err instanceof Error ? err.message : String(err);
        const error = new Error(`${String(operation)} failed: response body could not be read: ${cause}`);
        error.status = response.status;
        throw error;
    }
    let data = undefined;
    if (raw.length > 0) {
        try {
            data = JSON.parse(raw);
        }
        catch {
            if (response.ok) {
                const error = new Error(`${String(operation)} returned a non-JSON ${response.status} response: ${raw.slice(0, 200)}`);
                error.status = response.status;
                throw error;
            }
        }
    }
    if (!response.ok) {
        const message = (data &&
            typeof data === "object" &&
            ("error" in data || "message" in data) &&
            String(data.error ??
                data.message)) ||
            raw.slice(0, 200) ||
            response.statusText ||
            `HTTP ${response.status}`;
        const error = new Error(`${String(operation)} failed: ${String(message)}`);
        error.status = response.status;
        throw error;
    }
    return (data ?? null);
}
function jsonBody(value) {
    const body = JSON.stringify(value);
    if (body === undefined) {
        throw new TypeError("Application state values must be JSON-serializable. Use deleteClientAppState or setClientAppState with undefined to clear a key.");
    }
    return body;
}
/** Server caps a batch at 100 keys; stay under it when splitting. */
const MAX_BATCH_KEYS = 100;
export async function readClientAppStateMany(keys, options = {}) {
    assertAgentNativeApiEnabled(`read application state [${keys.join(", ")}]`);
    const unique = [...new Set(keys)];
    for (const key of unique)
        appStateUrl(key); // validates the key shape
    if (unique.length === 0)
        return { values: {}, missing: [] };
    const merged = { values: {}, missing: [] };
    for (let i = 0; i < unique.length; i += MAX_BATCH_KEYS) {
        const chunk = unique.slice(i, i + MAX_BATCH_KEYS);
        const browserHeaders = browserTabHeaders();
        const url = `${agentNativePath("/_agent-native/application-state")}?keys=${chunk
            .map(encodeURIComponent)
            .join(",")}`;
        const response = await fetch(url, {
            method: "GET",
            cache: "no-store",
            ...(browserHeaders ? { headers: browserHeaders } : {}),
            signal: options.signal,
        });
        const batch = await parseAppStateResponse(response, `Read application state [${chunk.join(", ")}]`);
        if (!batch || typeof batch !== "object" || !batch.values) {
            throw new Error(`Read application state [${chunk.join(", ")}] returned an unexpected payload.`);
        }
        Object.assign(merged.values, batch.values);
        merged.missing.push(...(batch.missing ?? []));
    }
    return merged;
}
// Reads issued in the same tick are coalesced into one batched request. Every
// mounted composer, question card and suggestion hook reads its own key on
// mount, which used to be one HTTP request (and one full identity resolution)
// each — ~55 on an analytics dashboard load.
let pendingBatch;
function scheduleBatchedRead(key) {
    if (pendingBatch) {
        pendingBatch.keys.add(key);
        return pendingBatch.promise;
    }
    const keys = new Set([key]);
    const promise = new Promise((resolve, reject) => {
        setTimeout(() => {
            pendingBatch = undefined;
            readClientAppStateMany([...keys]).then(resolve, reject);
        }, 0);
    });
    pendingBatch = { keys, promise };
    return promise;
}
function awaitWithAbort(promise, signal) {
    if (!signal)
        return promise;
    const abortReason = () => signal.reason ?? new Error("The operation was aborted");
    if (signal.aborted)
        return Promise.reject(abortReason());
    return new Promise((resolve, reject) => {
        const onAbort = () => {
            cleanup();
            reject(abortReason());
        };
        const cleanup = () => signal.removeEventListener("abort", onAbort);
        signal.addEventListener("abort", onAbort, { once: true });
        promise.then((value) => {
            cleanup();
            if (signal.aborted)
                reject(abortReason());
            else
                resolve(value);
        }, (error) => {
            cleanup();
            reject(error);
        });
    });
}
export async function readClientAppState(key, options = {}) {
    appStateUrl(key); // validates the key shape before it joins a batch
    if (options.signal?.aborted) {
        throw options.signal.reason ?? new Error("Aborted");
    }
    const batch = await awaitWithAbort(scheduleBatchedRead(key), options.signal);
    return (batch.values[key] ?? null);
}
export async function writeClientAppState(key, value, options = {}) {
    assertAgentNativeApiEnabled(`write application state "${key}"`);
    const response = await fetch(appStateUrl(key), {
        method: "PUT",
        headers: buildHeaders(options.requestSource),
        body: jsonBody(value),
        keepalive: options.keepalive,
        signal: options.signal,
    });
    return parseAppStateResponse(response, `Write application state "${key}"`);
}
export async function deleteClientAppState(key, options = {}) {
    assertAgentNativeApiEnabled(`delete application state "${key}"`);
    const response = await fetch(appStateUrl(key), {
        method: "DELETE",
        // DELETE carries no JSON body, so this custom header is the only
        // same-origin marker the CSRF check can see from an embedded frame.
        headers: {
            "X-Agent-Native-CSRF": "1",
            ...(browserTabHeaders() ?? {}),
            ...(options.requestSource
                ? { "X-Request-Source": options.requestSource }
                : {}),
        },
        keepalive: options.keepalive,
        signal: options.signal,
    });
    await parseAppStateResponse(response, `Delete application state "${key}"`);
}
export async function setClientAppState(key, value, options = {}) {
    if (value === null || value === undefined) {
        await deleteClientAppState(key, options);
        return null;
    }
    return writeClientAppState(key, value, options);
}
